/// An EXTENSION-METHOD class, not a Chain of Command class: no [ExtensionOf],
/// static, and every method static with a table or class first parameter. The
/// compiler enforces exactly this shape (EXT001 encodes its messages). COC002 and
/// COC003 used to treat the _Extension suffix alone as proof of a CoC class.
public static class FixtureStaticExtensionClass_Extension
{
}

Method.Source:
public static str displayGroupName(CustTable _custTable)
{
    CustGroup custGroup;

    select firstonly Name from custGroup
        where custGroup.CustGroup == _custTable.CustGroup;

    return custGroup.Name;
}

public static boolean hasOpenTransactions(CustTable _custTable, boolean _includeSettled = false)
{
    CustTrans custTrans;

    select firstonly RecId from custTrans
        where custTrans.AccountNum == _custTable.AccountNum
           && (_includeSettled || custTrans.Closed == dateNull());

    return custTrans.RecId != 0;
}
